{
 "command": "git ls-files && grep -rniE \"retention|RETENTION|purge|finaliz\" --include=* . | grep -v \"^./.git/\" | head -50",
 "description": "List files and search retention references"
}

{
 "mode": "filter",
 "query": "invoice retention purge refund",
 "include_invalidated": true
}

{
 "command": "cat migrations/*.sql scripts/backfill_tax.py docs/ops/backfills.md scripts/export.py && cat .engramdb/memories/use-structlog* .engramdb/memories/database-conn* | sed -n '1,200p'",
 "description": "Read schema, scripts, and related docs"
}

{
 "command": "cat src/billing/refunds.py src/billing/invoices.py pyproject.toml tests/test_db.py docker-compose.yml Makefile",
 "description": "Read refunds, invoices, config, and DB test"
}

{
 "command": "python -m py_compile scripts/purge_invoices.py && python scripts/purge_invoices.py --help | head -5; env -u DATABASE_URL python scripts/purge_invoices.py; echo rc=$?; python -c \"\nimport sys; sys.path.insert(0,'scripts'); import purge_invoices as p\nfrom datetime import datetime, timezone\nprint(p.cutoff(datetime(2026,10,4,tzinfo=timezone.utc)))\"",
 "description": "Compile and smoke-test the script"
}
